<div class="nx-page-head"><div><div class="nx-kicker">GOLDENSITE / RUTAS</div><h1>Un destino para cada visita.</h1><p>Detecta páginas ausentes y configura redirecciones internas sin bucles ni cambios en las rutas de acceso.</p></div><?= \App\Core\GoldensiteIcon::svg('monitor-redirects',38) ?></div><?php if ($status): ?><div class="nx-alert" role="status"><?= $e($status) ?></div><?php endif ?>
<div class="nx-operation-grid"><section class="nx-panel"><div class="nx-panel-head"><h2>Nueva redirección</h2></div><form method="post" class="nx-panel-body nx-stack"><input type="hidden" name="csrf_token" value="<?= $e($csrfToken) ?>"><input type="hidden" name="action" value="create"><label>Ruta de origen<input name="source_url" required maxlength="255" placeholder="/pagina-anterior" value="<?= $e(is_string($_GET['source']??null)?substr($_GET['source'],0,255):'') ?>"></label><label>Destino interno<input name="target_url" required maxlength="255" placeholder="/page/pagina-nueva"></label><label>Tipo<select name="redirect_type"><option value="301">301 · Permanente</option><option value="302">302 · Temporal</option><option value="307">307 · Temporal, conserva método</option><option value="308">308 · Permanente, conserva método</option></select></label><button class="nx-btn primary">Guardar redirección</button><p class="nx-note">El módulo debe estar activo para aplicar reglas públicas. Los registros no guardan la consulta, la IP ni el navegador del visitante.</p></form></section><section class="nx-panel"><div class="nx-panel-head"><h2>Reglas configuradas</h2></div><?php foreach ($rules as $rule): ?><article class="nx-tree-row"><strong class="nx-code"><?= $e($rule['source_url']) ?></strong><span class="nx-small">→ <?= $e($rule['target_url']) ?></span><span class="nx-pill"><?= $rule['redirect_type'] ?> · <?= $rule['hits'] ?> usos</span><form method="post"><input type="hidden" name="csrf_token" value="<?= $e($csrfToken) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= $rule['id'] ?>"><button class="nx-btn small danger">Eliminar regla</button></form></article><?php endforeach ?><?php if (!$rules): ?><p class="nx-empty">No hay redirecciones configuradas.</p><?php endif ?></section></div>
<section class="nx-panel" style="margin-top:24px"><div class="nx-panel-head"><h2>Rutas no encontradas</h2><form method="get" class="nx-filter"><input name="q" placeholder="Buscar ruta" aria-label="Buscar ruta" value="<?= $e($q) ?>"><button class="nx-btn small">Buscar</button></form></div><div class="nx-table-wrap"><table class="nx-table"><thead><tr><th>Ruta</th><th>Visitas registradas</th><th>Última detección</th><th>Acción</th></tr></thead><tbody><?php foreach ($logs as $log): ?><tr><td class="nx-code"><?= $e($log['url']) ?></td><td><?= $log['hits'] ?></td><td><?= $e($log['last_detected']) ?></td><td><a class="nx-btn small" href="?source=<?= rawurlencode($log['url']) ?>">Crear redirección</a></td></tr><?php endforeach ?></tbody></table></div><div class="nx-table-foot"><?php if ($page>1): ?><a href="?page=<?= $page-1 ?>&amp;q=<?= rawurlencode($q) ?>" class="nx-btn small">Anterior</a><?php endif ?><?php if (count($logs)===25): ?><a href="?page=<?= $page+1 ?>&amp;q=<?= rawurlencode($q) ?>" class="nx-btn small">Siguiente</a><?php endif ?></div></section>
